WITH recent_subscriptions AS (SELECT * FROM subscriptions WHERE monthly_fee > 130), summary AS (SELECT DATE_FORMAT(start_date, 'yyyy-MM') AS start_month, MAX(monthly_fee) AS max_monthly_fee, SUM(CASE WHEN plan = 'basic' THEN monthly_fee ELSE 0 END) AS basic_monthly_fee FROM recent_subscriptions GROUP BY DATE_FORMAT(start_date, 'yyyy-MM')) SELECT * FROM summary ORDER BY start_month;
